from collections import Counter
class Solution:
    def smallestPair(self, nums):
        c = Counter(nums)
        vals = sorted(c)
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                if c[vals[i]] != c[vals[j]]:
                    return [vals[i], vals[j]]
        return [-1, -1]

