class Solution {
public:
    vector<int> smallestPair(vector<int>& nums) {
        map<int,int> c;
        for (int x : nums) c[x]++;
        vector<int> vals;
        for (auto& [k, v] : c) vals.push_back(k);
        for (int i = 0; i < (int)vals.size(); i++)
            for (int j = i + 1; j < (int)vals.size(); j++)
                if (c[vals[i]] != c[vals[j]]) return {vals[i], vals[j]};
        return {-1, -1};
    }
};

