class Solution {
    public int[] smallestPair(int[] nums) {
        Map<Integer,Integer> c = new HashMap<>();
        for (int x : nums) c.merge(x, 1, Integer::sum);
        List<Integer> vals = new ArrayList<>(new TreeSet<>(c.keySet()));
        for (int i = 0; i < vals.size(); i++)
            for (int j = i + 1; j < vals.size(); j++) {
                int x = vals.get(i), y = vals.get(j);
                if (!c.get(x).equals(c.get(y))) return new int[]{x, y};
            }
        return new int[]{-1, -1};
    }
}

