var smallestPair = function(nums) {
    const c = new Map();
    for (const x of nums) c.set(x, (c.get(x) || 0) + 1);
    const vals = [...c.keys()].sort((a, b) => a - b);
    for (let i = 0; i < vals.length; i++)
        for (let j = i + 1; j < vals.length; j++)
            if (c.get(vals[i]) !== c.get(vals[j])) return [vals[i], vals[j]];
    return [-1, -1];
};
